(1582392, 212929, 37893, '<td valign="top">Ah! Hearst Castle. Nice capture especially since it''s dark down there in the Roman Pool.</td>', 'Ah! Hearst Castle. Nice capture especially since it''s dark down there in the Roman Pool.', '2005-08-03 02:35:29.000000', NULL, 1),
(1582393, 209811, 30490, '<td valign="top">Way too out of focus for my taste</td>', 'Way too out of focus for my taste', '2005-08-03 02:35:31.000000', NULL, 1),
(1582395, 212012, 30490, '<td valign="top">This just doesn''t seem to fit the challenge to me.  Maybe it is the post processing, but this image just isn''t appealing due to the colors and the cropping.</td>', 'This just doesn''t seem to fit the challenge to me.  Maybe it is the post processing, but this image just isn''t appealing due to the colors and the cropping.', '2005-08-03 02:36:48.000000', NULL, 1),
(1582398, 212171, 30490, '<td valign="top">At least have the complete cookie in focus for gosh sake!  I won''t say it isn''t on topic (although this isn''t an image that says affluence to me) but the tight cropping and the lack of DOF just isn''t working on this one.</td>', 'At least have the complete cookie in focus for gosh sake!  I won''t say it isn''t on topic (although this isn''t an image that says affluence to me) but the tight cropping and the lack of DOF just isn''t working on this one.', '2005-08-03 02:38:53.000000', NULL, 1),
(1582399, 211205, 41561, '<td valign="top">Traveling in red carpet style</td>', 'Traveling in red carpet style', '2005-08-03 02:39:17.000000', NULL, 1),
(1582400, 212958, 30490, '<td valign="top">Affluence?  How?  Great shadow shot, but I don''t see how it ties to the topic</td>', 'Affluence?  How?  Great shadow shot, but I don''t see how it ties to the topic', '2005-08-03 02:39:30.000000', NULL, 1),
