(1585935, 210951, 31443, '<td valign="top">Perfect photo and a beautiful little girl, you are indeed affluent!</td>', 'Perfect photo and a beautiful little girl, you are indeed affluent!', '2005-08-04 04:10:07.000000', NULL, 1),
