(1589823, 212662, 33560, '<td valign="top">I''ve seen a lot of good architectural photos at this site, but this one beats them all; spectactular.  Placement of the shadowy figure in the lower right corner has transformed a good photo into a great one.   Bravo.</td>', 'I''ve seen a lot of good architectural photos at this site, but this one beats them all; spectactular.  Placement of the shadowy figure in the lower right corner has transformed a good photo into a great one.   Bravo.', '2005-08-06 00:00:50.000000', NULL, 1),
(1589838, 211477, 37234, '<td valign="top">Wow. I''ll be VERY interested to see how this one was done. Definately the most creative shot I''ve seen for this challenge. The fog almost looks like a skull.</td>', 'Wow. I''ll be VERY interested to see how this one was done. Definately the most creative shot I''ve seen for this challenge. The fog almost looks like a skull.', '2005-08-06 00:12:41.000000', NULL, 1),
