(1590705, 209759, 36231, '<td valign="top">Hey ... you don''t want those, I''ll take em! :) Interesting capture. Good luck!</td>', 'Hey ... you don''t want those, I''ll take em! :) Interesting capture. Good luck!', '2005-08-06 11:32:13.000000', NULL, 1),
(1590770, 212688, 35545, '<td valign="top">Nice colors.  I wish you hadn''t cut the bottom off the inflatable flamingo.  Good humor.  How did you get the dog to sit still?</td>', 'Nice colors.  I wish you hadn''t cut the bottom off the inflatable flamingo.  Good humor.  How did you get the dog to sit still?', '2005-08-06 12:14:35.000000', NULL, 1),
(1590775, 212579, 35545, '<td valign="top">I wish there was some way you could have gotten the complete circle of the wheels instead of cutting them off.  Good tones, and I like the curve of the fender.</td>', 'I wish there was some way you could have gotten the complete circle of the wheels instead of cutting them off.  Good tones, and I like the curve of the fender.', '2005-08-06 12:17:23.000000', NULL, 1),
(1590788, 212851, 35545, '<td valign="top">A differnt take on the subject.</td>', 'A differnt take on the subject.', '2005-08-06 12:21:51.000000', NULL, 1),
