(1596732, 210989, 25678, '<td valign="top">A little bit of contrast and color adjustment will help this picture not seem as flat</td>', 'A little bit of contrast and color adjustment will help this picture not seem as flat', '2005-08-09 00:30:11.000000', NULL, 1),
(1596741, 212469, 40155, '<td valign="top">eerie</td>', 'eerie', '2005-08-09 00:33:28.000000', NULL, 1),
(1596747, 212384, 25678, '<td valign="top">I like how this picture seems to be thinking a bit outside the box.  This looks like a performance shot of some type, and I find the motion blur a little distracting.  I''d recommend bumping up the iso, and/or opening your aperture up.  Most performance photographer I know shoot a f/2.8 iso 800 minimum.   The cropping is also a bit odd.  I think cropping closer to the guy so his arm is cropped closer to his body will help.  Good luck</td>', 'I like how this picture seems to be thinking a bit outside the box.  This looks like a performance shot of some type, and I find the motion blur a little distracting.  I''d recommend bumping up the iso, and/or opening your aperture up.  Most performance photographer I know shoot a f/2.8 iso 800 minimum.   The cropping is also a bit odd.  I think cropping closer to the guy so his arm is cropped closer to his body will help.  Good luck', '2005-08-09 00:34:47.000000', NULL, 1),
(1596751, 209878, 25678, '<td valign="top">I find the refelctions to distracting.  The aren''t strong enought o be a strong part of the picture, but they aren''t weak enough to really see the window display.</td>', 'I find the refelctions to distracting.  The aren''t strong enought o be a strong part of the picture, but they aren''t weak enough to really see the window display.', '2005-08-09 00:35:47.000000', NULL, 1),
